const char *tr(StrId id, uint8_t lang) {
    if ((unsigned)id >= S_KEY_COUNT) return "";
    if (lang >= LANG_COUNT) lang = LANG_EN;
    const char *s = lang == LANG_AZ ? s_az[id] : s_strings[id][lang];
    if (!s) s = s_strings[id][LANG_EN];
    return s ? s : "";
}

const char *lang_name(uint8_t lang) {
    static const char *const names[LANG_COUNT] = { "English", "Türkçe", "Español", "Deutsch", "Français", "Azərbaycanca" };
    return names[lang < LANG_COUNT ? lang : 0];
}
